use
std.arena;
use
std.io;
model
Node
{
value:
i32
;
next:
ref
Node;
}
/// Allocate a new Node from the arena
def
new_node
(arena:
ref
Arena, value:
i32
):
ref
Node {
mut
n:
ref
Node = Arena.alloc(arena, sizeof(Node));
n.value = value;
n.next =
nil
;
return
n;
}
/// Push a new value to the front of the list
def
list_push_front
(head:
ref
Node, arena:
ref
Arena, value:
i32
):
ref
Node {
mut
new_head = new_node(arena, value);
new_head.next = head;
return
new_head;
}
