Parallel Processing Made Simple
/// Process data in parallel across multiple threads
def
parallel_processing
(data:
i32
[], size:
i32
) {
parallel for mut
i =
0
; i < size; i++ {
// Each iteration runs in parallel
data[i] = data[i] *
2
;
}
}
/// Compute intensive operations benefit from parallelism
def
matrix_multiply
(a:
f64
[][], b:
f64
[][], n:
i32
) {
parallel for mut
i =
0
; i < n; i++ {
for mut
j =
0
; j < n; j++ {
mut
sum =
0.0
;
for mut
k =
0
; k < n; k++ {
sum = sum + a[i][k] * b[k][j];
}
}
}
}
Conway's Game of Life
/// Counts the live neighbors
def
count_neighbors
(grid:
i32
[height][width], x:
i32
, y:
i32
,
width:
i32
, height:
i32
):
i32
{
mut
count:
i32
=
0
;
for mut
dy =
-1
; dy <=
1
; dy++ {
for mut
dx =
-1
; dx <=
1
; dx++ {
if
dx ==
0
and
dy ==
0
{
continue
; }
val
nx = x + dx;
val
ny = y + dy;
if
nx >=
0
and
nx < width
and
ny >=
0
and
ny < height {
count = count + grid[ny][nx];
}
}
}
return
count;
}
/// Compute next generation
def
next_generation
(grid:
i32
[height][width],
new_grid:
i32
[height][width],
width:
i32
, height:
i32
) {
for mut
y =
0
; y < height; y++ {
for mut
x =
0
; x < width; x++ {
val
neighbors = count_neighbors(grid, x, y, width, height);
if
grid[y][x] ==
1
{
new_grid[y][x] = (neighbors ==
2
or
neighbors ==
3
) ?
1
:
0
;
}
else
{
new_grid[y][x] = neighbors ==
3
?
1
:
0
;
}
}
}
}
